// Everything Copper Kettle needs in the QuickBooks sandbox (Project 3 design doc, section 5b).
// Names must match the category and branch names used by the invoice workflow.
const vendors = [
  ['Highland Bean Roasters', 'Highland Bean Roasters LLC'],
  ['Meadow Dairy Co.', 'Meadow Dairy Co.'],
  ['PackRight Packaging Supply', 'PackRight Packaging Supply, Inc.'],
  ['BrightClean Commercial Services', 'BrightClean Commercial Services LLC'],
];
const accounts = [
  'Coffee & Tea', 'Dairy & Milk Alternatives', 'Food & Bakery', 'To-Go Packaging & Disposables',
  'Kitchen & Cleaning Supplies', 'Cleaning & Maintenance Services', 'Freight & Delivery Fees', 'Sales Tax Paid',
];
const classes = ['Larimer St', 'Highlands', 'Wash Park', 'Shared'];
const items = [];
for (const [display, company] of vendors) items.push({ kind: 'vendor', name: display, body: { DisplayName: display, CompanyName: company } });
for (const a of accounts) items.push({ kind: 'account', name: a, body: { Name: a, AccountType: 'Expense' } });
for (const c of classes) items.push({ kind: 'class', name: c, body: { Name: c } });
return items.map(json => ({ json }));

// One line per item: created (with its QuickBooks ID), already there, or failed.
const asked = $('QuickBooks Setup List').all().map(i => i.json);
const rows = $input.all().map((it, i) => {
  const r = it.json || {};
  const req = asked[i] || {};
  const body = r.body || {};
  const key = req.kind === 'vendor' ? 'Vendor' : req.kind === 'account' ? 'Account' : 'Class';
  const fault = body.Fault && body.Fault.Error && body.Fault.Error[0];
  let status;
  if (r.statusCode === 200 && body[key]) status = 'created (id ' + body[key].Id + ')';
  else if (fault && /duplicate/i.test(fault.Message + ' ' + (fault.Detail || ''))) status = 'already exists';
  else status = 'FAILED ' + r.statusCode + ': ' + (fault ? fault.Message + ' – ' + (fault.Detail || '') : JSON.stringify(body).slice(0, 200));
  return { kind: req.kind, name: req.name, status, id: body[key] ? body[key].Id : null };
});
return [{ json: { failed: rows.filter(r => r.status.startsWith('FAILED')).length, rows } }];

// Sanity check of the answer key as stored in n8n: counts and sums.
// Only T08 should have lines that do not add up to the subtotal (by design).
const CATS = ['coffee_tea','dairy','food','packaging','supplies','cleaning_services','freight'];
const BRANCHES = ['larimer','highlands','washpark','shared'];
const out = [];
for (const it of $input.all()) {
  const r = it.json;
  let lines = [];
  try { lines = JSON.parse(r.line_items || '[]'); } catch (e) { out.push(r.case_id + ': line_items is not valid JSON'); continue; }
  if (lines.length !== Number(r.line_count)) out.push(r.case_id + ': ' + lines.length + ' lines, line_count says ' + r.line_count);
  if (r.expect_is_invoice !== 'yes') continue;
  const sum = Math.round(lines.reduce((s, l) => s + l.amount, 0) * 100) / 100;
  if (Math.abs(sum - Number(r.subtotal)) > 0.005) out.push(r.case_id + ': lines add up to ' + sum.toFixed(2) + ', subtotal ' + r.subtotal);
  const tot = Math.round((Number(r.subtotal) + Number(r.tax)) * 100) / 100;
  if (Math.abs(tot - Number(r.total)) > 0.005) out.push(r.case_id + ': subtotal + tax = ' + tot + ', total ' + r.total);
  for (const l of lines) {
    if (Math.abs(Math.round(l.quantity * l.unit_price * 100) / 100 - l.amount) > 0.005) out.push(r.case_id + ': line math off for ' + l.description);
    if (!CATS.includes(l.category)) out.push(r.case_id + ': bad category ' + l.category);
    if (!BRANCHES.includes(l.branch)) out.push(r.case_id + ': bad branch ' + l.branch);
  }
}
return [{ json: { rows: $input.all().length, findings: out } }];
